export const LIMIT_KEYS = ["maxCandidates", "maxRecords", "maxSources", "maxBytes", "maxTokens", "maxMillis"];

export const effectiveLimits = ({ service, policy, request }) => Object.fromEntries(
  LIMIT_KEYS.map((key) => {
    const values = [service?.[key], policy?.[key], request?.[key]];
    if (!values.every((value) => Number.isInteger(value) && value > 0)) throw new TypeError(`invalid limit ${key}`);
    return [key, Math.min(...values)];
  })
);

export const requestLifetime = ({ deadlineAt, cancelled = false, now = Date.now() }) => {
  if (cancelled) return { active: false, reasonCode: "CANCELLED" };
  const deadline = Date.parse(deadlineAt);
  if (!Number.isFinite(deadline)) throw new TypeError("invalid deadlineAt");
  if (now >= deadline) return { active: false, reasonCode: "DEADLINE_REACHED" };
  return { active: true, remainingMillis: deadline - now };
};

export const TOKEN_ESTIMATOR = Object.freeze({ id: "utf8-bytes-div-4", version: "1.0.0" });
export const estimateTokens = (value) => Math.ceil(Buffer.byteLength(typeof value === "string" ? value : JSON.stringify(value), "utf8") / 4);

const PRECEDENCE = [
  ["denied", "denied"],
  ["invalid", "invalid_request"],
  ["temporaryFailure", "temporary_failure"],
  ["stale", "stale"],
  ["conflict", "conflict"],
  ["budgetExceeded", "budget_exceeded"],
  ["insufficientEvidence", "insufficient_evidence"],
  ["noMatch", "no_match"],
  ["partial", "partial"]
];

export const resolveStatus = (conditions) => {
  for (const [condition, status] of PRECEDENCE) if (conditions[condition] === true) return status;
  return "ok";
};

export const STATUS_PRECEDENCE = Object.freeze(PRECEDENCE.map(([, status]) => status));

import assert from "node:assert/strict";
import test from "node:test";
import { effectiveLimits, estimateTokens, requestLifetime, TOKEN_ESTIMATOR } from "../src/effective-limits.mjs";

const limits = (value) => ({ maxCandidates: value, maxRecords: value, maxSources: value, maxBytes: value, maxTokens: value, maxMillis: value });

test("effective caps are minimums before reads", () => {
  assert.deepEqual(effectiveLimits({ service: limits(100), policy: limits(20), request: limits(50) }), limits(20));
  assert.throws(() => effectiveLimits({ service: limits(100), policy: limits(20), request: { ...limits(50), maxBytes: 0 } }), /invalid limit/);
});

test("request lifetime stops on cancellation or deadline", () => {
  assert.deepEqual(requestLifetime({ deadlineAt: "2026-08-03T00:00:01Z", now: Date.parse("2026-08-03T00:00:00Z") }), { active: true, remainingMillis: 1000 });
  assert.deepEqual(requestLifetime({ deadlineAt: "2026-08-03T00:00:01Z", cancelled: true }), { active: false, reasonCode: "CANCELLED" });
  assert.deepEqual(requestLifetime({ deadlineAt: "2026-08-03T00:00:00Z", now: Date.parse("2026-08-03T00:00:00Z") }), { active: false, reasonCode: "DEADLINE_REACHED" });
});

test("token estimate names a stable algorithm", () => {
  assert.deepEqual(TOKEN_ESTIMATOR, { id: "utf8-bytes-div-4", version: "1.0.0" });
  assert.equal(estimateTokens("12345"), 2);
});

import assert from "node:assert/strict";
import test from "node:test";
import { resolveStatus, STATUS_PRECEDENCE } from "../src/status-resolver.mjs";

test("status precedence is deterministic", () => {
  assert.deepEqual(STATUS_PRECEDENCE, ["denied", "invalid_request", "temporary_failure", "stale", "conflict", "budget_exceeded", "insufficient_evidence", "no_match", "partial"]);
  assert.equal(resolveStatus({ denied: true, conflict: true }), "denied");
  assert.equal(resolveStatus({ conflict: true, partial: true }), "conflict");
  assert.equal(resolveStatus({ partial: true }), "partial");
  assert.equal(resolveStatus({}), "ok");
});
